mapper.select:
SELECT count(*) FROM fin.corp_tax_pay t WHERE to_char(t.pay_plan_dt,'YYYY-MM')=#{month}
  AND NOT EXISTS(SELECT 1 FROM fin.pay p WHERE p.pay_src_cd='AUTO_FIN' AND p.pay_se_cd='CORP_TAX'
    AND p.src_rec_id=t.tax_pay_id AND p.pay_stts_cd!='CANCEL')

mapper.update:
UPDATE fin.mth_cls SET cls_stts_cd=CASE WHEN #{action}='CLOSE' THEN 'CLOSED' ELSE 'OPEN' END,
cls_at=#{at},cls_user_id=#{actor}
rls_at=#{at},rls_user_id=#{actor},rls_rsn_desc=#{reason}
WHERE cls_ym=#{month} AND cls_stts_cd=CASE WHEN #{action}='CLOSE' THEN 'OPEN' ELSE 'CLOSED' END
